import assert from "node:assert/strict";
import http from "node:http";
import { createRequire, isBuiltin } from "node:module";
import WebSocket, { WebSocketServer } from "ws";
assert.equal(WebSocket.WebSocketServer, WebSocketServer);
assert.equal(WebSocket.Server, WebSocketServer);
assert.equal(import.meta.require("ws"), WebSocket);
const require = createRequire(import.meta.url);
assert.equal(require("ws"), WebSocket);
assert.equal(require.resolve.paths("ws"), null);
assert.equal(isBuiltin("ws"), true);
assert.equal(isBuiltin("bun:not-a-module"), false);
const server = http.createServer();
const wss = new WebSocketServer({ server, perMessageDeflate: false });
wss.on("connection", socket => socket.on("message", data => socket.send(data)));
server.listen(0, "127.0.0.1");
await new Promise(resolve => server.once("listening", resolve));
const client = new WebSocket(`ws://127.0.0.1:${server.address().port}/echo`, { perMessageDeflate: false });
const done = Promise.withResolvers();
client.on("error", done.reject);
client.on("open", () => client.send("real ws package"));
client.on("message", data => { assert.equal(data.toString(), "real ws package"); client.close(); });
client.on("close", done.resolve);
await done.promise;
await new Promise(resolve => wss.close(resolve));
await new Promise(resolve => server.close(resolve));
console.log("builtin ws client and server exchange a message and close");
